process {
    withName: VAMB_BIN {
        accelerator = 1
        // Vamb uses one device, so serialise to avoid GPU contention
        maxForks    = 1
        ext.args    = '-o C -e 5 -q 2 3 --minfasta 1 --seed 1'
    }
}
